CREATE OR REPLACE FUNCTION public.imp_cinta_datos() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.pesajes_cintas_lotes; BEGIN SELECT * INTO l FROM public.pesajes_cintas_lotes WHERE id=NEW.lote_id; IF l.imp_bobina_id IS NOT NULL THEN IF NOT public.user_sees_planta(auth.uid(),l.planta_corte_id) OR NOT public.can_edit_module(auth.uid(),'pesaje_cintas') THEN RAISE EXCEPTION 'Sin permiso para cortes de esta planta' USING ERRCODE='42501'; END IF; IF nullif(btrim(l.datos_calidad_snapshot->>'sku'),'') IS NULL THEN RAISE EXCEPTION 'necesita atención Calidad SKU'; END IF; IF NEW.estatus_liberacion IS NULL THEN NEW.estatus_liberacion:=CASE l.datos_calidad_snapshot->>'estado' WHEN 'liberada' THEN 'L' WHEN 'rechazada' THEN 'NC' ELSE 'C' END; END IF; END IF; RETURN NEW; END $$;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.registrar_cinta_v3(uuid,integer,numeric,numeric,text,text,text,uuid)'::regprocedure) INTO d; d:=replace(d,'SELECT * INTO v_lote FROM public.pesajes_cintas_lotes WHERE id = _lote_id; IF v_lote.imp_bobina_id IS NOT NULL THEN v_sku := v_lote.datos_calidad_snapshot->>''sku''; END IF; IF v_lote.imp_bobina_id IS NULL AND v_sku IS NOT NULL AND NOT EXISTS','IF v_sku IS NOT NULL AND NOT EXISTS'); EXECUTE d; END $$;
COMMENT ON COLUMN public.pesajes_cintas.sku_sap IS 'SKU of the cut tape, not the mother roll; imported mother SKU retained separately in lote datos_calidad_snapshot.sku.';